# Create a standalone R script and reproducibility bundle.

make_standalone_script <- function(approved_rules, root = ".", import_options = list()) {
  rules_text <- paste(capture.output(dput(approved_rules)), collapse = "\n")
  import_options <- do.call(normalize_import_options, import_options)
  import_text <- paste(capture.output(dput(import_options)), collapse = "\n")
  c(
    "# Generated by CodebookR. Only researcher-approved rules are included.",
    "# Usage: Rscript preprocessing.R original_data.csv [cleaned_data.rds]",
    "# IMPORTANT: inspect approved rules; this script does not run any AI code.",
    "",
    standalone_definitions(),
    "",
    paste0("approved_rules <- ", rules_text),
    paste0("import_options <- ", import_text),
    "args <- commandArgs(trailingOnly = TRUE)",
    "if (length(args) < 1L) stop('Usage: Rscript preprocessing.R path/to/original_data.csv [output.rds]')",
    "input_path <- args[[1]]",
    "output_path <- if (length(args) >= 2L) args[[2]] else 'cleaned_data.rds'",
    "raw_data <- do.call(read_dataset, c(list(path = input_path), import_options))",
    "result <- apply_approved_rules(raw_data, approved_rules)",
    "saveRDS(result$data, output_path)",
    "audit_path <- paste0(tools::file_path_sans_ext(output_path), '_audit.csv')",
    "write.csv(result$audit, audit_path, row.names = FALSE, fileEncoding = 'UTF-8')",
    "cat('Done:', normalizePath(output_path), '\\n')"
  )
}

export_bundle <- function(path, result, approved_rules, metadata,
                          source_name, root = ".", import_options = list(), review = NULL) {
  if (!requireNamespace("zip", quietly = TRUE)) {
    stop("install.packages('zip')\ub97c \uba3c\uc800 \uc2e4\ud589\ud558\uc138\uc694.", call. = FALSE)
  }
  dir <- tempfile("codebookr-export-")
  dir.create(dir, recursive = TRUE)
  on.exit(unlink(dir, recursive = TRUE, force = TRUE), add = TRUE)
  saveRDS(result$data, file.path(dir, "cleaned_data.rds"))
  write.csv(approved_rules, file.path(dir, "approved_rules.csv"),
            row.names = FALSE, na = "", fileEncoding = "UTF-8")
  write.csv(result$audit, file.path(dir, "audit.csv"),
            row.names = FALSE, fileEncoding = "UTF-8")
  write.csv(metadata, file.path(dir, "before_metadata.csv"),
            row.names = FALSE, fileEncoding = "UTF-8")
  write.csv(variable_metadata(result$data), file.path(dir, "after_metadata.csv"),
            row.names = FALSE, fileEncoding = "UTF-8")
  writeLines(capture.output(utils::sessionInfo()),
             file.path(dir, "session_info.txt"), useBytes = TRUE)
  writeLines(make_standalone_script(approved_rules, root = root, import_options = import_options),
             file.path(dir, "preprocessing.R"), useBytes = TRUE)
  writeLines(c(
    "CodebookR reproducibility bundle",
    paste("Original filename:", basename(source_name)),
    paste("Created (local time):", format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z")),
    "",
    "cleaned_data.rds: approved transformations applied to uploaded data",
    "approved_rules.csv: approved operations, evidence and versioned JSON parameters",
    "audit.csv: affected observations, missingness, dimensions and calculation notes",
    "audit.csv details: JSON with reference counts/means/scales or reshape mappings",
    "before_metadata.csv / after_metadata.csv: variable-level metadata summaries",
    "preprocessing.R: standalone R script; run with the ORIGINAL raw data path",
    "CSV encoding and explicitly selected character columns are recorded in the script.",
    "session_info.txt: R and package versions at bundle export time",
    "",
    "Rscript preprocessing.R path/to/original_data.csv reproduced.rds",
    "Packages: readr, haven, jsonlite, tidyr, vctrs and tidyselect (install.packages).",
    "Calculated reference values are recomputed on the supplied data; fixed values stay fixed.",
    "The generated code does not include API keys, AI responses, or raw row values.",
    "CSV may lose labelled attributes; use RDS for primary output."
  ), file.path(dir, "README.txt"), useBytes = TRUE)
  if (!is.null(review)) {
    reports <- c(mapping = "variable_mapping.csv", definitions = "codebook_definitions.csv", comparison = "codebook_review.csv", documents = "codebook_documents.csv", after_comparison = "codebook_after_review.csv")
    for (key in names(reports)) {
      write.csv(review[[key]], file.path(dir, reports[[key]]), row.names = FALSE, na = "", fileEncoding = "UTF-8")
    }
    cat("\ncodebook_review.csv describes ORIGINAL data; codebook_after_review.csv describes the BASIC processed data.\nExecution does not resolve all review findings. Check source documents for unparsed instructions.\nvariable_mapping.csv: explicit source-to-data variable links\ncodebook_definitions.csv: definitions and source locations, including missing-code meanings\ncodebook_review.csv: comparisons, unresolved findings and researcher decisions\ncodebook_documents.csv: parsing coverage and limits\ncodebook_after_review.csv: codebook comparisons after basic processing (before additions)\nBasic rule IDs: ", paste(review$basic_rule_ids, collapse = ", "), "\n", file = file.path(dir, "README.txt"), append = TRUE, sep = "")
  }
  files <- list.files(dir, full.names = FALSE)
  zip::zipr(zipfile = path, files = files, root = dir, include_directories = FALSE)
  invisible(path)
}

# Follow only bindings owned by this package. Dependency functions retain their
# explicit pkg:: calls; neither user data nor AI responses are treated as code.
standalone_definitions <- function() {
  owner <- environment(apply_approved_rules)
  pending <- c("read_dataset", "apply_approved_rules")
  seen <- character()
  output <- character()
  while (length(pending)) {
    name <- pending[[1L]]
    pending <- pending[-1L]
    if (name %in% seen || !exists(name, envir = owner, inherits = FALSE)) next
    seen <- c(seen, name)
    value <- get(name, envir = owner, inherits = FALSE)
    if (is.function(value)) {
      pending <- unique(c(pending, codetools::findGlobals(value)))
    }
    output <- c(output, paste0(name, " <- "), deparse(value, width.cutoff = 100L), "")
  }
  output
}
